"""Tiny generated fixtures for the opt-in temporary-account GUI test only."""
import base64,io,math,struct,wave

def audio():
    output=io.BytesIO()
    with wave.open(output,"wb") as stream:
        stream.setnchannels(1);stream.setsampwidth(2);stream.setframerate(8000)
        stream.writeframes(b"".join(struct.pack("<h",int(math.sin(i*.1)*12000)) for i in range(8000)))
    return output.getvalue()

def video():
    # One second of a generated red rectangle, H.264/MP4, no external content.
    return base64.b64decode('')
